
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_rscan_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_rscan", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.650614761751478e-02, -2.645882252980328e-02, -2.638868332841950e-02, -2.628338990626678e-02, -2.612248222256263e-02, -2.587084631309427e-02, -2.546906321611512e-02, -2.485498418897615e-02, -2.418366488575361e-02, -2.491266778132022e-02, -3.073692101729469e-02, -4.854975527192703e-02, -3.771926950716346e-02, -2.436444761419202e-02, -1.921548563541981e-02, -1.368605364532894e-02, -5.601354653913110e-03, -1.022547074949042e-03, -5.659070189281083e-05, -5.478217175351092e-07]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


